'use strict';

// MODULES //
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrmmeanvar = require( '@stdlib/stats/incr/mmeanvar' );
var isArrayLike = require( '@stdlib/assert/is-array-like' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving arithmetic mean and unbiased sample variance, skipping NaN values.
*
* @param {(ArrayLike|PositiveInteger)} out - output array or window size
* @param {PositiveInteger} [W] - window size
* @throws {TypeError} must provide a positive integer number for window size
* @returns {Function} accumulator function
*
* @example
* var acc = incrnanmmeanvar( 3 );
* acc( 2.0 ); // returns [ 2, 0 ]
* acc( NaN ); // returns [ 2, 0 ] (NaN skipped)
* acc( 4.0 ); // returns [ 3, 2 ]
*
* @example
* var out = [ 0.0, 0.0 ];
* var acc = incrnanmmeanvar( out, 3 );
* acc( 2.0 );
* console.log( out ); // returns [ 2, 0 ]
*/
function incrnanmmeanvar( out, W ) {
	var mmeanvar;

	// Detect signature: (W) or (out, W)
	if ( isArrayLike( out ) ) {
		mmeanvar = incrmmeanvar( out, W );
	} else {
		mmeanvar = incrmmeanvar( out );
	}

	return accumulator;

	/**
	* Accumulator function.
	*
	* @param {number} [x] - input value
	* @returns {(Array|null)} current mean and variance
	* @private
	*/
	function accumulator( x ) {
		// If no arguments → return current state:
		if ( arguments.length === 0 ) {
			return mmeanvar();
		}
		// Skip NaNs (do not update):
		if ( isnan( x ) ) {
			return mmeanvar();
		}
		// Update with valid number:
		return mmeanvar( x );
	}
}


// EXPORTS //

module.exports = incrnanmmeanvar;
